   PHẦN 4. KIỂM TRA NHANH
   ===================================================================== */
SELECT 'TaiKhoan' AS bang, COUNT(*) AS soDong FROM dbo.TaiKhoan UNION ALL
SELECT 'TheLoai', COUNT(*) FROM dbo.TheLoai UNION ALL
SELECT 'Phim', COUNT(*) FROM dbo.Phim UNION ALL
SELECT 'PhimTheLoai', COUNT(*) FROM dbo.PhimTheLoai UNION ALL
SELECT 'PhongChieu', COUNT(*) FROM dbo.PhongChieu UNION ALL
SELECT 'LoaiVe', COUNT(*) FROM dbo.LoaiVe UNION ALL
SELECT 'DoiTuong', COUNT(*) FROM dbo.DoiTuong UNION ALL
SELECT 'LoaiVeDoiTuong', COUNT(*) FROM dbo.LoaiVeDoiTuong UNION ALL
SELECT 'Ghe', COUNT(*) FROM dbo.Ghe UNION ALL
SELECT 'NgayLe', COUNT(*) FROM dbo.NgayLe UNION ALL
SELECT 'QuyTacGia', COUNT(*) FROM dbo.QuyTacGia UNION ALL
SELECT 'LichSuGia', COUNT(*) FROM dbo.LichSuGia UNION ALL
SELECT 'SuatChieu', COUNT(*) FROM dbo.SuatChieu UNION ALL
SELECT 'DonHang', COUNT(*) FROM dbo.DonHang UNION ALL
SELECT 'GheSuatChieu', COUNT(*) FROM dbo.GheSuatChieu UNION ALL
SELECT 'Ve', COUNT(*) FROM dbo.Ve UNION ALL
SELECT 'ThucPham', COUNT(*) FROM dbo.ThucPham UNION ALL
SELECT 'ChiTietThucPham', COUNT(*) FROM dbo.ChiTietThucPham UNION ALL
SELECT 'LichSuTonKho', COUNT(*) FROM dbo.LichSuTonKho UNION ALL
SELECT 'GiaoDich', COUNT(*) FROM dbo.GiaoDich UNION ALL
SELECT 'CaiDat', COUNT(*) FROM dbo.CaiDat UNION ALL
SELECT 'NhatKySaoLuu', COUNT(*) FROM dbo.NhatKySaoLuu;

-- Ví dụ: 10 ngày doanh thu gần nhất
SELECT TOP 10 * FROM dbo.vw_DoanhThuNgay ORDER BY ngay DESC;
-- Ví dụ: xếp hạng phim theo số vé bán
SELECT * FROM dbo.vw_ThongKePhim WHERE soSuat > 0 ORDER BY soVeBan DESC;
GO
